+    it('should allow all requests when not in read-only mode', async () => {
+      controller = new AccessController({
+        readOnlyMode: false
+      });
+
+      const mockRequest = {
+        method: 'POST',
+        url: '/api/specs'
+      } as FastifyRequest;
+      
+      const mockReply = {
+        code: jest.fn().mockReturnThis(),
+        send: jest.fn()
+      } as unknown as FastifyReply;
